window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[122]={"id":"122","numero":122,"titre":"Principales techniques de rééducation et de réadaptation","objectifs":[{"id":"122-1","rang":"A","rubrique":"Définition","titre":"Connaître le rôle du médecin","contenu":"<p>Le <strong><span class=\"kw-def\">médecin de soins primaires</span></strong> (médecin généraliste) est le pivot de la rééducation : il apporte une réponse à <span class=\"kw-chiffre\">90 %</span> des patients dans <span class=\"kw-chiffre\">90 %</span> des situations.</p>\n      <p>Il prescrit et coordonne un <strong><span class=\"kw-def\">programme de rééducation « simple »</span></strong> :</p>\n      <ul>\n        <li>Collaboration d'un médecin — quelle que soit sa spécialité — et d'un <span class=\"kw-def\">auxiliaire médical</span> (kinésithérapeute, orthophoniste surtout)</li>\n        <li>Pas de nécessité d'évaluation spécialisée ni de coordination spécifique</li>\n      </ul>\n      <p><strong>Indications courantes</strong> d'un programme simple :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Arthrose des membres</span>, <span class=\"kw-clinique\">pathologie rachidienne chronique</span>, pathologies péri-articulaires</li>\n        <li><span class=\"kw-clinique\">Entorse de cheville</span></li>\n        <li>Lutte contre <span class=\"kw-clinique\">les</span> conséquences de l'<span class=\"kw-clinique\">immobilité</span> et du décubitus chez la personne âgée</li>\n        <li>Traitement de l'<span class=\"kw-clinique\">incontinence urinaire</span> chez la femme</li>\n        <li>Prise en charge orthophonique de difficultés de langage simples de l'enfant (bégaiement, troubles de l'articulation)</li>\n      </ul>\n      <p>Deux autres rôles du médecin de soins primaires :</p>\n      <ul>\n        <li><strong>MDPH</strong> — renseignement des dossiers médicaux en vue d'un dépôt de dossier à la <span class=\"kw-def\">MDPH</span></li>\n        <li><strong>Adresser</strong> — orienter le patient vers une consultation spécialisée de <span class=\"kw-def\">MPR</span> lorsque la situation nécessite une évaluation ou une prise en charge plus complexe</li>\n      </ul>","frequence":0},{"id":"122-2","rang":"A","rubrique":"Définition","titre":"Connaître le rôle du médecin de médecine physique et réadaptation (MPR)","contenu":"<p>Le <strong><span class=\"kw-def\">médecin de MPR</span></strong> a pour objectif l'évaluation, la prévention et la <span class=\"kw-ttt\">réduction</span> — au minimum inévitable — des <span class=\"kw-def\">déficiences</span>, des <span class=\"kw-def\">limitations d'activités</span> et des <span class=\"kw-def\">restrictions de participation sociale</span>, quelle qu'en soit l'étiologie, dans <span class=\"kw-clinique\">les</span> domaines des fonctions motrices, cognitives, vésicosphinctériennes et cardiorespiratoires.</p>\n      <p><strong>Lieux d'exercice</strong> :</p>\n      <ul>\n        <li>Milieu hospitalier — <span class=\"kw-def\">centres hospitaliers</span> ou centres de soins de suite et de réadaptation (<strong><span class=\"kw-def\">SSR</span></strong>) polyvalents ou spécialisés</li>\n        <li>Milieu institutionnel — secteur médico-social</li>\n        <li>Exercice en libéral possible mais minoritaire</li>\n      </ul>\n      <p><strong>Démarche propre à la MPR</strong> — 6 étapes :</p>\n      <ol>\n        <li>Examen médical du patient et analyse de la situation selon la <span class=\"kw-def\">CIF</span></li>\n        <li>Détermination d'objectifs à court terme et fixation des objectifs à long terme avec le patient (<span class=\"kw-def\">projet de vie</span>)</li>\n        <li>Établissement du programme de traitement précisant <span class=\"kw-clinique\">les</span> différents intervenants</li>\n        <li>Mise en œuvre du traitement par <span class=\"kw-clinique\">les</span> différents intervenants</li>\n        <li>Bilans réguliers et évaluation de la situation</li>\n        <li>Ajustement des objectifs en fonction de l'<span class=\"kw-clinique\">évolution</span></li>\n      </ol>\n      <div class=\"callout callout-info\">\n        <strong>Programme « complexe ».</strong> Il nécessite la collaboration d'un médecin spécialiste en MPR et de <span class=\"kw-clinique\">plusieurs auxiliaires de rééducation</span> — à distinguer du programme « simple » coordonné par le médecin de soins primaires.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 118 — Personne handicapé</em></p>","frequence":0},{"id":"122-3","rang":"A","rubrique":"Définition","titre":"Connaître le rôle des auxiliaires médicaux","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">auxiliaires médicaux</span></strong> sont des professionnels de santé qui exercent des actes de rééducation, le plus souvent <span class=\"kw-clinique\">sur prescription médicale</span> : infirmiers, masseurs-kinésithérapeutes, pédicures-podologues, orthophonistes, orthoptistes, ergothérapeutes, psychomotriciens, diététiciens, audioprothésistes, manipulateurs d'électroradiologie, aides-soignants.</p>\n      <p>Pour <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">professions de rééducation</span>, la prise en charge des actes en libéral par la CPAM dépend de la profession :</p>\n      <table >\n        <thead>\n          <tr><th>Profession</th><th>Lieu d'exercice principal</th><th>Remboursement CPAM (libéral)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Masseur-kinésithérapeute</strong></td><td>Libéral (<span class=\"kw-chiffre\">80 %</span>)</td><td>Oui</td></tr>\n          <tr><td><strong>Pédicure-podologue</strong></td><td>Libéral (<span class=\"kw-chiffre\">98 %</span>)</td><td>Oui (remboursement faible)</td></tr>\n          <tr><td><strong>Orthophoniste</strong></td><td>Libéral (<span class=\"kw-chiffre\">81 %</span>)</td><td>Oui</td></tr>\n          <tr><td><strong>Orthoptiste</strong></td><td>Libéral (<span class=\"kw-chiffre\">67 %</span>)</td><td>Oui</td></tr>\n          <tr><td><strong>Ergothérapeute</strong></td><td>Salarié (<span class=\"kw-chiffre\">91 %</span>)</td><td><span class=\"kw-alerte\">Non remboursé</span></td></tr>\n          <tr><td><strong>Psychomotricien</strong></td><td>Salarié (<span class=\"kw-chiffre\">82 %</span>)</td><td><span class=\"kw-alerte\">Non remboursé</span></td></tr>\n          <tr><td><strong>Diététicien</strong></td><td>Salarié (<span class=\"kw-chiffre\">68 %</span>)</td><td><span class=\"kw-alerte\">Non remboursé</span></td></tr>\n        </tbody>\n      </table>\n      <p>L'<strong>infirmier</strong> et l'<strong>aide-soignant</strong> participent aussi à la rééducation : prévention et prise en charge des troubles de l'<span class=\"kw-clinique\">immobilité</span> et du décubitus, pansements complexes (escarres), <span class=\"kw-def\">éducation thérapeutique</span> (autosondages vésicosphinctériens), accompagnement actif au quotidien.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Ne font <span class=\"kw-alerte\">PAS partie des professions de santé</span> : <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">professions du social</span> (assistants de service social, psychologues) et les professions correspondant à l'usage d'un titre (psychothérapeutes, ostéopathes).\n      </div>","frequence":2},{"id":"122-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales indications d’un programme de rééducation","contenu":"<p>Un <strong><span class=\"kw-def\">programme de rééducation</span></strong> est indiqué dès qu'une <span class=\"kw-def\">déficience</span>, une limitation d'activité ou une restriction de participation est accessible à une prise en charge rééducative. <span class=\"kw-clinique\">Les</span> actes peuvent être effectués selon deux grands cadres :</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>En ville</strong></td><td>Secteur libéral — mais tous <span class=\"kw-clinique\">les</span> acteurs de la rééducation ne sont pas accessibles en libéral</td></tr>\n          <tr><td><strong>En institution</strong></td><td>\n            <strong>Milieu sanitaire :</strong> <span class=\"kw-alerte\">hospitalisation</span> conventionnelle ou de jour ; service de soins de suite et de réadaptation (SSR)<br>\n            <strong>Milieu médico-social</strong><br>\n            <strong>Coordination :</strong> par un médecin spécialiste, ou par un médecin spécialiste en MPR si la prise en charge est lourde ou complexe\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Orientation</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Rééducation externe</span> le plus souvent — pour la majorité des cas nécessitant une rééducation simple</li>\n        <li><span class=\"kw-def\">Hospitalisation spécialisée en MPR</span> (complète ou de jour) dans <span class=\"kw-clinique\">les</span> situations les plus complexes, par exemple après un <span class=\"kw-clinique\">AVC sévère</span></li>\n      </ul>","frequence":1},{"id":"122-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principaux objectifs de la rééducation","contenu":"<p>La rééducation poursuit trois grands types d'objectifs, hiérarchisés selon le caractère réductible ou non de la déficience :</p>\n      <table >\n        <thead><tr><th>Objectif</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Réduction</span> de la déficience</strong><br>(objectifs symptomatiques)</td><td>\n            <span class=\"kw-def\">Guérison</span> possible dans de nombreuses situations : <span class=\"kw-clinique\">douleurs</span>, <span class=\"kw-clinique\">déficit moteur</span>, <span class=\"kw-clinique\">encombrement bronchique</span>, troubles de déglutition<br>\n            Récupération d'une <span class=\"kw-clinique\">désadaptation cardiaque</span> ou d'une <span class=\"kw-clinique\">lésion</span> neurologique limitée\n          </td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Réduction</span> des conséquences</strong></td><td>Réduire <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">limitations d'activité</span> et les <span class=\"kw-def\">restrictions de participation</span> lorsque la déficience n'est pas réductible</td></tr>\n          <tr><td><strong>Compensation du désavantage</strong><br>(objectifs situationnels)</td><td>Compenser le retentissement dans la vie quotidienne et sociale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Rééducation <span class=\"kw-bio\">vs</span> réadaptation.</strong> La <span class=\"kw-def\">rééducation</span> vise à aider l'individu à réduire <span class=\"kw-clinique\">les</span> déficiences et les limitations d'activités ; la <span class=\"kw-def\">réadaptation</span> vise à l'aider à s'y adapter lorsqu'elles sont stabilisées et persistantes.\n      </div>","frequence":1},{"id":"122-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales indications d’un programme de kinésithérapie","contenu":"<p>La <strong><span class=\"kw-def\">kinésithérapie</span></strong> est indiquée devant toute atteinte fonctionnelle dans le champ du mouvement et de la motricité. Principales indications :</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Douleur et trophicité</strong></td><td><span class=\"kw-clinique\">Douleur</span> ; <span class=\"kw-clinique\">œdème</span> ; troubles trophiques ; troubles sensitifs</td></tr>\n          <tr><td><strong>Motricité</strong></td><td>Altération de la <span class=\"kw-clinique\">commande motrice</span> ; <span class=\"kw-clinique\">faiblesse musculaire</span> ; troubles du tonus musculaire</td></tr>\n          <tr><td><strong>Articulation</strong></td><td><span class=\"kw-clinique\">Raideurs articulaires</span> ; instabilité articulaire ; gênes à la préhension</td></tr>\n          <tr><td><strong>Fonction</strong></td><td><span class=\"kw-ci\">Intolérance</span> à l'effort ; gênes aux déplacements ; <span class=\"kw-clinique\">encombrement bronchique</span> ; troubles vésicosphinctériens</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Prise en charge CPAM.</strong> La CPAM rembourse <span class=\"kw-chiffre\">sans accord préalable</span> un nombre limité de séances pour <span class=\"kw-chiffre\">14 indications</span> de rééducation référencées. Au-delà de ce nombre, une <span class=\"kw-def\">demande d'accord préalable</span> est nécessaire ; dans <span class=\"kw-clinique\">les</span> autres situations, aucune demande préalable n'est requise.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 94 — Rachialgie · 125 — Trouble miction - incontinence urinaire · 120 — Complications immobilité - décubitus</em></p>","frequence":4},{"id":"122-7","rang":"B","rubrique":"Définition","titre":"Connaître les principales techniques de kinésithérapie","contenu":"<p><span class=\"kw-clinique\">Les</span> techniques de <span class=\"kw-def\">masso-kinésithérapie</span> se répartissent en cinq grandes familles :</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Techniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Massages</strong></td><td>Pressions glissées superficielles ou profondes ; pressions statiques (<span class=\"kw-clinique\">contractures musculaires</span>) ; massage transverse profond (<span class=\"kw-clinique\">tendinites</span>, <span class=\"kw-ttt\">drainage</span> lymphatique)</td></tr>\n          <tr><td><strong>Amplitude articulaire</strong></td><td>Postures (maintien prolongé d'une articulation) ; mobilisations actives (par le patient, en l'absence de troubles moteurs) ; mobilisations passives (manuelles par le kiné, ou mécanisées par robots arthromoteurs)</td></tr>\n          <tr><td><strong>Travail musculaire</strong><br>(contraction active contre résistance)</td><td>Renforcement <span class=\"kw-def\">isométrique</span> (sans déplacement articulaire, très utilisé) ; <span class=\"kw-def\">isotonique</span> (charge constante) ; <span class=\"kw-def\">isocinétique</span> (vitesse constante, surtout en pathologie du sport)</td></tr>\n          <tr><td><strong>Physiothérapie</strong><br>(agents physiques)</td><td>Ultrasons ; chaleur et <span class=\"kw-ttt\">cryothérapie</span> ; <span class=\"kw-ttt\">kinébalnéothérapie</span> (effet <span class=\"kw-ttt\">antalgique</span>, allègement du poids du corps) ; électrostimulation musculaire (renforcement) ; <span class=\"kw-ttt\">TENS</span> (but <span class=\"kw-ttt\">antalgique</span>)</td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-ttt\">Drainage</span> respiratoire ; réentraînement à l'effort ; renforcement de la sensibilité proprioceptive ; techniques sensorimotrices (neurologie centrale) ; <span class=\"kw-ttt\">biofeedback</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"122-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales indications d’un programme d’ergothérapie","contenu":"<p>L'<strong><span class=\"kw-def\">ergothérapie</span></strong> (« thérapie par le travail ») a pour objectif le maintien ou l'accession de l'individu à un maximum d'<span class=\"kw-def\">autonomie</span> dans son environnement quotidien. Elle intervient quand une déficience limite <span class=\"kw-clinique\">les</span> activités du patient (soins personnels, déplacements, communication).</p>\n      <p><strong>Principales indications</strong> :</p>\n      <ul>\n        <li>Installation et positionnement</li>\n        <li><span class=\"kw-clinique\">Déficience du membre supérieur</span> : motrice, sensitive ou articulaire</li>\n        <li>Pertes d'autonomie liées à des limitations d'activités physiques : <span class=\"kw-clinique\">troubles de la préhension</span>, perte d'autonomie dans <span class=\"kw-clinique\">les</span> déplacements</li>\n        <li>Pertes d'autonomie liées à des limitations cognitives : troubles des fonctions supérieures (<span class=\"kw-clinique\">mémoire</span>, <span class=\"kw-clinique\">praxie</span>, fonctions exécutives, communication)</li>\n      </ul>\n      <p>L'ergothérapeute évalue <span class=\"kw-clinique\">les</span> activités, propose des <span class=\"kw-ttt\">aides techniques</span> et des aménagements de l'environnement (domicile, outils scolaires, plan de travail) et peut réaliser des orthèses de posture ou de fonction.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Remboursement.</strong> <span class=\"kw-alerte\">Aucun acte d'ergothérapie en libéral n'est remboursé</span> par l'assurance maladie. Le recours se fait via un service de MPR ; en cas de reconnaissance par la MDPH, <span class=\"kw-clinique\">les</span> actes en libéral peuvent être pris en charge via une <span class=\"kw-def\">PCH</span>, sous réserve d'une prescription médicale.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 118 — Personne handicapé · 56 — Enfant handicapé</em></p>","frequence":0},{"id":"122-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales indications de l’orthophonie","contenu":"<p>L'<strong><span class=\"kw-def\">orthophonie</span></strong> concerne tous <span class=\"kw-clinique\">les</span> âges — du jeune enfant au sujet très âgé — devant des pathologies variées d'origine <span class=\"kw-etio\">neurologique</span>, <span class=\"kw-etio\">ORL</span> et/ou <span class=\"kw-etio\">développementale</span>. Elle assure la prévention, l'évaluation et la rééducation des troubles suivants :</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Troubles pris en charge</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Langage et communication</strong></td><td>Difficultés d'intégration scolaire ; <span class=\"kw-clinique\">troubles du langage écrit et oral</span> ; troubles de la communication dans leurs aspects non langagiers</td></tr>\n          <tr><td><strong>Sphère ORL et déglutition</strong></td><td><span class=\"kw-clinique\">Troubles de la déglutition</span> ; troubles de la voix (<span class=\"kw-clinique\">dysphonie</span>) ; troubles de l'articulation (<span class=\"kw-clinique\">dysarthrie</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège annale.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">troubles du langage</span> (écrit et oral) relèvent d'une <span class=\"kw-def\">fonction cognitive</span> et sont à bien distinguer de la <span class=\"kw-alerte\">dysarthrie</span>, qui est un trouble de l'<span class=\"kw-def\">articulation</span>.\n      </div>\n      <p><span class=\"kw-clinique\">Les</span> actes d'orthophonie sont <span class=\"kw-clinique\">remboursés</span> par la caisse d'assurance maladie.</p>","frequence":8},{"id":"122-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les règles de prescription de la massokinésithérapie","contenu":"<p>La prescription de <strong><span class=\"kw-def\">masso-kinésithérapie</span></strong> obéit à des règles strictes, fréquemment évaluées à l'EDN. À la fin du programme, le masseur-kinésithérapeute adresse un bilan au prescripteur.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Éléments obl<span class=\"kw-chiffre\">iga</span>toires</strong></td><td>\n            Nature de la prescription : « <span class=\"kw-def\">masso-kinésithérapie</span> »<br>\n            Identification du prescripteur : nom, prénom, coordonnées, n° <span class=\"kw-def\">ADELI</span>, <span class=\"kw-def\">RPPS</span><br>\n            Identification du patient : nom, prénom<br>\n            <span class=\"kw-clinique\">Indication médicale</span> : région à traiter (pour la cotation de l'acte)<br>\n            Date de rédaction et signature du prescripteur\n          </td></tr>\n          <tr><td><strong>Selon le contexte</strong></td><td>\n            Intitulé « kinébalnéothérapie » ou « rééducation en piscine » ; <span class=\"kw-ci\">contre-indications</span> à certaines techniques (ex. <span class=\"kw-ci\">électrostimulation et pacemaker</span>) ; mention « à domicile » ou « avec transport sanitaire » ; « accident de travail » ; « dimanche et jours fériés » ; « acte d'<span class=\"kw-alerte\">urgence</span> » ; <span class=\"kw-def\">ordonnance bizone</span> si le traitement est lié à une <span class=\"kw-def\">ALD</span>\n          </td></tr>\n          <tr><td><strong>Possible mais non obl<span class=\"kw-chiffre\">iga</span>toire</strong></td><td>Objectif de la rééducation ; techniques à utiliser ; nombre et fréquence des séances — <span class=\"kw-ci\">à éviter</span>, le kinésithérapeute étant plus compétent pour <span class=\"kw-clinique\">les</span> déterminer</td></tr>\n          <tr><td><strong>Interdit</strong></td><td>Le <span class=\"kw-alerte\">diagnostic ne doit pas figurer sur l'ordonnance</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège annale.</strong> Le diagnostic ne figure jamais sur l'ordonnance de masso-kinésithérapie ; il est conseillé d'y associer un <span class=\"kw-def\">courrier</span> précisant le diagnostic et <span class=\"kw-clinique\">les</span> éléments du contexte clinique. Les mentions « à renouveler » ou « qsp » ne s'appliquent pas : l'ordonnance est valable <span class=\"kw-chiffre\">1 an</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 328 — Thérapeutique non médicamenteuse/dispositifs</em></p>","frequence":1},{"id":"122-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les règles de prescription de l’orthophonie","contenu":"<p><span class=\"kw-clinique\">Les</span> actes d'orthophonie sont effectués <span class=\"kw-clinique\">sur prescription médicale</span>, donc sur indication(s) médicale(s). Deux types de prescription de bilan peuvent être demandés :</p>\n      <table >\n        <thead><tr><th>Type de prescription</th><th>Déroulé</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bilan orthophonique avec rééducation si nécessaire</strong></td><td>\n            1. L'orthophoniste réalise un bilan<br>\n            2. Si des séances de rééducation sont nécessaires, il établit un compte rendu adressé au prescripteur (objectifs, nombre et nature des séances qu'il détermine)<br>\n            3. Il établit une <span class=\"kw-def\">demande d'entente préalable</span>\n          </td></tr>\n          <tr><td><strong>Bilan orthophonique d'invest<span class=\"kw-chiffre\">iga</span>tion</strong></td><td>\n            1. L'orthophoniste réalise un bilan<br>\n            2. Il établit un compte rendu adressé au prescripteur : <span class=\"kw-def\">diagnostic orthophonique</span> et propositions<br>\n            3. Le prescripteur peut alors prescrire une rééducation orthophonique<br>\n            4. L'orthophoniste établit une <span class=\"kw-def\">demande d'entente préalable</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> À la fin du traitement, une <span class=\"kw-def\">note d'évolution</span> est adressée au prescripteur.\n      </div>","frequence":0},{"id":"122-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les règles d’arrêt de la rééducation","contenu":"<p>La rééducation est arrêtée dans deux grandes situations :</p>\n      <ul>\n        <li><strong>Objectifs atteints</strong> — <span class=\"kw-clinique\">les</span> objectifs fixés sont atteints, ou le patient est devenu <span class=\"kw-clinique\">asymptomatique</span></li>\n        <li><strong>Objectifs non atteints</strong>, pour l'une des raisons suivantes :\n          <ul>\n            <li>Le <span class=\"kw-alerte\">patient n'est pas coopérant</span></li>\n            <li>La <span class=\"kw-alerte\">prescription n'était pas adaptée</span> : la rééducation n'est pas la solution</li>\n            <li>La rééducation est <span class=\"kw-alerte\">mal tolérée</span> : elle n'est finalement pas adaptée, même bien conduite</li>\n          </ul>\n        </li>\n      </ul>","frequence":0},{"id":"122-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications de la rééducation d’entretien","contenu":"<p>La <strong><span class=\"kw-def\">rééducation d'entretien</span></strong> vise à pérenniser <span class=\"kw-clinique\">les</span> résultats obtenus à l'issue d'un programme de rééducation.</p>\n      <ul>\n        <li><strong>Principe</strong> — le kinésithérapeute apprend au patient un programme d'exercices personnels (<span class=\"kw-def\">auto-rééducation</span>) : programmes simples, comprenant un nombre limité d'exercices</li>\n        <li><strong>Rythme</strong> — habituellement <span class=\"kw-chiffre\">2 séances par semaine</span></li>\n        <li><strong>Prescription discontinue</strong> de courtes séries (<span class=\"kw-chiffre\">10 à 15 séances</span>), justifiée pour :\n          <ul>\n            <li>Retrouver un niveau fonctionnel précédent qui s'est détérioré au fil du temps</li>\n            <li>Réviser la qualité technique des exercices du programme d'auto-entretien</li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Alternative.</strong> Des activités physiques encadrées par un <span class=\"kw-def\">éducateur sportif spécialisé</span> peuvent être proposées en alternative ou en <span class=\"kw-bio\">complément</span>.\n      </div>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"3960f5c5af0b","n":122,"o":"122-1","u":"Définition","t":"Connaître le rôle du médecin","q":"Quel est le rôle pivot du médecin de soins primaires dans la rééducation d'un patient ?","a":"<p>Le médecin de soins primaires (médecin généraliste) est le <strong>pivot</strong> de la rééducation. Il apporte une réponse à <strong>90% des patients</strong> dans <strong>90% des situations</strong>, en prescrivant et coordonnant un programme de rééducation « simple ».</p>"},{"i":"55cfe5d9b742","n":122,"o":"122-1","u":"Définition","t":"Connaître le rôle du médecin","q":"Au-delà de la coordination des programmes simples, quels sont les deux autres rôles fondamentaux du médecin de soins primaires en rééducation ?","a":"<p>Le médecin de soins primaires a deux autres rôles fondamentaux :</p><ul><li>Renseigner les <strong>dossiers médicaux</strong> en vue d'un dépôt de dossier à la <strong>MDPH</strong>.</li><li>Adresser et orienter le patient vers une <strong>consultation spécialisée de Médecine Physique et de Réadaptation (MPR)</strong> lorsque la situation est plus complexe et nécessite une évaluation ou une prise en charge spécifique.</li></ul>"},{"i":"ab178598544d","n":122,"o":"122-1","u":"Définition","t":"Connaître le rôle du médecin","q":"Dans quels cas un programme de rééducation simple, coordonné par le médecin traitant, est-il indiqué ?","a":"<p>Les indications courantes d'un programme de rééducation simple sont :</p><ul><li>L'<strong>arthrose des membres</strong></li><li>Les <strong>pathologies rachidiennes chroniques</strong></li><li>Les <strong>pathologies péri-articulaires</strong></li><li>L'<strong>entorse de cheville</strong></li><li>La lutte contre les conséquences de l'<strong>immobilité et du décubitus</strong> chez la personne âgée</li><li>Le traitement de l'<strong>incontinence urinaire chez la femme</strong></li><li>La prise en charge orthophonique de <strong>difficultés de langage simples de l'enfant</strong> (bégaiement, troubles de l'articulation)</li></ul>"},{"i":"3cc5191c0c5f","n":122,"o":"122-10","u":"Prise en charge","t":"Connaître les règles de prescription de la massokinésithérapie","q":"Quels sont les éléments obligatoires à mentionner sur une ordonnance de masso-kinésithérapie ?","a":"<p>Les éléments obligatoires sur une ordonnance de masso-kinésithérapie sont :</p><ul><li>La nature de la prescription : <strong>« masso-kinésithérapie »</strong>.</li><li>L'identification du prescripteur : <strong>nom, prénom, coordonnées, n° ADELI ou RPPS</strong>.</li><li>L'identification du patient : <strong>nom, prénom</strong>.</li><li>L'<strong>indication médicale</strong> : <strong>région à traiter</strong>, essentielle pour la cotation de l'acte.</li><li>La <strong>date de rédaction</strong> et la <strong>signature</strong> du prescripteur.</li></ul>"},{"i":"91003eb796cf","n":122,"o":"122-10","u":"Prise en charge","t":"Connaître les règles de prescription de la massokinésithérapie","q":"Quelles sont les mentions spécifiques à ajouter sur une ordonnance de masso-kinésithérapie, en fonction du contexte clinique ?","a":"<p>Selon le contexte clinique, les mentions spécifiques à ajouter sur une ordonnance de masso-kinésithérapie incluent :</p><ul><li>L'intitulé <strong>« kinébalnéothérapie »</strong> ou <strong>« rééducation en piscine »</strong>.</li><li>Les <strong>contre-indications à certaines techniques</strong> (ex. : électrostimulation et pacemaker).</li><li>La mention <strong>« à domicile »</strong> ou <strong>« avec transport sanitaire »</strong>.</li><li>La mention <strong>« accident de travail »</strong>.</li><li>L'indication <strong>« dimanche et jours fériés »</strong>.</li><li>La mention <strong>« acte d'urgence »</strong>.</li><li>La précision <strong>ordonnance bizone</strong> si le traitement est lié à une <strong>ALD</strong> (Affection de Longue Durée).</li></ul>"},{"i":"ad1e6cd9f410","n":122,"o":"122-10","u":"Prise en charge","t":"Connaître les règles de prescription de la massokinésithérapie","q":"Quelles informations NE DOIVENT PAS figurer sur une ordonnance de masso-kinésithérapie et pourquoi ?","a":"<p>Sur une ordonnance de masso-kinésithérapie :</p><ul><li>Le <strong>diagnostic ne doit JAMAIS figurer</strong> directement. Il est conseillé de l'associer à un <strong>courrier précisant le diagnostic et les éléments du contexte clinique</strong>.</li><li>L'<strong>objectif de la rééducation</strong>, les <strong>techniques à utiliser</strong>, le <strong>nombre et la fréquence des séances</strong> ne sont <strong>pas obligatoires</strong> et sont même <strong>à éviter</strong>, le kinésithérapeute étant plus compétent pour les déterminer.</li><li>Les mentions <strong>« à renouveler »</strong> ou <strong>« qsp »</strong> (quantité suffisante pour) <strong>ne s'appliquent pas</strong>, l'ordonnance étant valable <strong>un an</strong>.</li></ul>"},{"i":"6af48b4f7fd3","n":122,"o":"122-11","u":"Prise en charge","t":"Connaître les règles de prescription de l’orthophonie","q":"Dans quel cadre un bilan d'orthophonie peut-il être réalisé ?","a":"<p>Un bilan d'orthophonie est réalisé uniquement après <strong>prescription médicale</strong>.</p>"},{"i":"7ca4d2bed0d3","n":122,"o":"122-11","u":"Prise en charge","t":"Connaître les règles de prescription de l’orthophonie","q":"Que doit adresser l'orthophoniste au médecin prescripteur à la fin d'un traitement orthophonique ?","a":"<p>À la fin du traitement, une <strong>note d'évolution</strong> doit être adressée au prescripteur.</p>"},{"i":"7fcd50ec4080","n":122,"o":"122-11","u":"Prise en charge","t":"Connaître les règles de prescription de l’orthophonie","q":"Quel est le rôle de l'orthophoniste après un bilan orthophonique avec rééducation si nécessaire ?","a":"<p>L'orthophoniste réalise le bilan. Si des séances sont nécessaires, il établit un <strong>compte rendu</strong> pour le prescripteur (objectifs, nature et nombre de séances) et une <strong>demande d'entente préalable</strong>.</p>"},{"i":"bb47023d423d","n":122,"o":"122-11","u":"Prise en charge","t":"Connaître les règles de prescription de l’orthophonie","q":"Quels sont les deux types de prescriptions de bilan orthophonique possibles pour le médecin prescripteur ?","a":"<ul><li>Le <strong>bilan orthophonique avec rééducation si nécessaire</strong>.</li><li>Le <strong>bilan orthophonique d'investigation</strong>.</li></ul>"},{"i":"cd63af92892b","n":122,"o":"122-11","u":"Prise en charge","t":"Connaître les règles de prescription de l’orthophonie","q":"Quel est le rôle de l'orthophoniste et du médecin suite à un bilan orthophonique d'investigation ?","a":"<p>L'orthophoniste réalise le bilan et établit un <strong>compte rendu</strong> avec diagnostic et propositions. Le <strong>médecin</strong> peut alors prescrire une rééducation. L'orthophoniste établit ensuite une <strong>demande d'entente préalable</strong>.</p>"},{"i":"560c5a8d52e3","n":122,"o":"122-2","u":"Définition","t":"Connaître le rôle du médecin de médecine physique et réadaptation (MPR)","q":"Quelles sont les étapes de la démarche propre à la MPR ?","a":"<p>La démarche propre à la MPR comporte six étapes :</p><ul><li><strong>Examen médical</strong> du patient et analyse de la situation selon la <strong>CIF</strong> (Classification Internationale du Fonctionnement, du handicap et de la santé)</li><li>Détermination et fixation d'<strong>objectifs</strong> (court et long terme) avec le patient (<strong>projet de vie</strong>)</li><li>Établissement du <strong>programme de traitement</strong> précisant les différents intervenants</li><li>Mise en œuvre du traitement par les différents intervenants</li><li><strong>Bilans réguliers</strong> et évaluation de la situation</li><li><strong>Ajustement des objectifs</strong> en fonction de l'évolution</li></ul>"},{"i":"af69f9c737ab","n":122,"o":"122-2","u":"Définition","t":"Connaître le rôle du médecin de médecine physique et réadaptation (MPR)","q":"Quel est l'objectif principal du médecin de Médecine Physique et de Réadaptation (MPR) ?","a":"<p>L'objectif du médecin de MPR est <strong>l'évaluation, la prévention et la réduction</strong> des <strong>déficiences</strong>, des <strong>limitations d'activités</strong> et des <strong>restrictions de participation sociale</strong>, quelle qu'en soit l'étiologie.</p>"},{"i":"c50a7b1b6595","n":122,"o":"122-2","u":"Définition","t":"Connaître le rôle du médecin de médecine physique et réadaptation (MPR)","q":"Dans quels domaines fonctionnels le médecin de MPR intervient-il ?","a":"<p>Le médecin de MPR intervient dans les domaines fonctionnels suivants :</p><ul><li>Fonctions <strong>motrices</strong></li><li>Fonctions <strong>cognitives</strong></li><li>Fonctions <strong>vésicosphinctériennes</strong></li><li>Fonctions <strong>cardiorespiratoires</strong></li></ul>"},{"i":"ce38bd4f97b1","n":122,"o":"122-2","u":"Définition","t":"Connaître le rôle du médecin de médecine physique et réadaptation (MPR)","q":"Qu'est-ce qui caractérise un programme de rééducation dit 'complexe' en MPR ?","a":"<p>Un programme de rééducation dit 'complexe' nécessite la <strong>collaboration d'un médecin spécialiste en MPR</strong> et de <strong>plusieurs auxiliaires de rééducation</strong>, à la différence d'un programme 'simple' coordonné par le médecin de soins primaires.</p>"},{"i":"1a92c854ead4","n":122,"o":"122-3","u":"Définition","t":"Connaître le rôle des auxiliaires médicaux","q":"Quelles professions de rééducation libérales sont remboursées par la CPAM, et lesquelles ne le sont pas ?","a":"<ul><li>Les professions <strong>remboursées</strong> par la CPAM en libéral sont : le <strong>masseur-kinésithérapeute</strong>, le <strong>pédicure-podologue</strong> (remboursement faible), l'<strong>orthophoniste</strong> et l'<strong>orthoptiste</strong>.</li><li>Les professions <strong>non remboursées</strong> en libéral sont : l'<strong>ergothérapeute</strong>, le <strong>psychomotricien</strong> et le <strong>diététicien</strong>.</li></ul>"},{"i":"968dd2fcdabe","n":122,"o":"122-3","u":"Définition","t":"Connaître le rôle des auxiliaires médicaux","q":"Quelle est la définition générale des auxiliaires médicaux et leur rôle principal ?","a":"<p>Les auxiliaires médicaux sont des professionnels de santé qui exercent des <strong>actes de rééducation</strong>, le plus souvent sur <strong>prescription médicale</strong>.</p>"},{"i":"a4cf12492528","n":122,"o":"122-3","u":"Définition","t":"Connaître le rôle des auxiliaires médicaux","q":"Quel est le rôle spécifique de l'infirmier et de l'aide-soignant dans la rééducation ?","a":"<p>L'infirmier et l'aide-soignant participent à la rééducation par :</p><ul><li>La <strong>prévention et prise en charge des troubles de l'immobilité et du décubitus</strong>.</li><li>Les <strong>pansements complexes</strong> (ex: escarres).</li><li>L'<strong>éducation thérapeutique</strong> (ex: autosondages vésicosphinctériens).</li><li>L'<strong>accompagnement actif</strong> au quotidien.</li></ul>"},{"i":"c10fbc673b15","n":122,"o":"122-3","u":"Définition","t":"Connaître le rôle des auxiliaires médicaux","q":"Quelles professions ne font PAS partie des professions de santé, malgré leur implication dans l'accompagnement des patients ?","a":"<p>Ne font PAS partie des professions de santé :</p><ul><li>Les <strong>professions du social</strong> (assistants de service social, psychologues).</li><li>Les <strong>professions correspondant à l'usage d'un titre</strong> (psychothérapeutes, ostéopathes).</li></ul>"},{"i":"01aa8aa53b41","n":122,"o":"122-4","u":"Prise en charge","t":"Connaître les principales indications d’un programme de rééducation","q":"Quand l'hospitalisation spécialisée en MPR est-elle indiquée ?","a":"<p>L'hospitalisation spécialisée en MPR (complète ou de jour) est indiquée dans les <strong>situations les plus complexes</strong>, par exemple après un <strong>AVC sévère</strong>, lorsque la rééducation externe n'est pas suffisante.</p>"},{"i":"71fc57d4be0e","n":122,"o":"122-4","u":"Prise en charge","t":"Connaître les principales indications d’un programme de rééducation","q":"Qui assure la coordination d'un programme de rééducation, notamment en cas de prise en charge lourde ou complexe ?","a":"<p>La coordination est assurée par un <strong>médecin spécialiste</strong>. Si la prise en charge est lourde ou complexe, elle relève d'un <strong>médecin spécialiste en MPR</strong> (Médecine Physique et de Réadaptation).</p>"},{"i":"a67886649967","n":122,"o":"122-4","u":"Prise en charge","t":"Connaître les principales indications d’un programme de rééducation","q":"Quels sont les deux grands cadres où les actes de rééducation peuvent être effectués ?","a":"<ul><li>Le cadre <strong>en ville</strong>, principalement dans le secteur libéral.</li><li>Le cadre <strong>en institution</strong>, qui peut être en milieu sanitaire (hospitalisation conventionnelle ou de jour, SSR) ou en milieu médico-social.</li></ul>"},{"i":"c5fa2b81ccd6","n":122,"o":"122-4","u":"Prise en charge","t":"Connaître les principales indications d’un programme de rééducation","q":"Dans quel contexte général est indiqué un programme de rééducation selon l'EDN ?","a":"<p>Un programme de rééducation est indiqué dès qu'une <strong>déficience</strong>, une <strong>limitation d'activité</strong> ou une <strong>restriction de participation</strong> est accessible à une prise en charge rééducative.</p>"},{"i":"3b7366cb9c33","n":122,"o":"122-5","u":"Prise en charge","t":"Connaître les principaux objectifs de la rééducation","q":"Quel est l'objectif de la rééducation lorsque l'on vise la réduction de la déficience ?","a":"<p>L'objectif de la rééducation axée sur la <strong>réduction de la déficience</strong> est de permettre une <strong>guérison ou une amélioration significative</strong> des symptômes. Cela est possible dans des situations comme les <strong>douleurs</strong>, un <strong>déficit moteur</strong>, un <strong>encombrement bronchique</strong> ou des <strong>troubles de la déglutition</strong>, ou encore la récupération d'une désadaptation cardiaque ou d'une lésion neurologique limitée.</p>"},{"i":"5f77c0818243","n":122,"o":"122-5","u":"Prise en charge","t":"Connaître les principaux objectifs de la rééducation","q":"Quels sont les trois grands types d'objectifs de la rééducation, hiérarchisés selon la réductibilité de la déficience ?","a":"<p>Les trois grands types d'objectifs de la rééducation sont :</p><ul><li>La <strong>réduction de la déficience</strong> (objectifs symptomatiques).</li><li>La <strong>réduction des conséquences</strong> (limitation d'activité et restriction de participation).</li><li>La <strong>compensation du désavantage</strong> (objectifs situationnels).</li></ul>"},{"i":"6a42e98641c5","n":122,"o":"122-5","u":"Prise en charge","t":"Connaître les principaux objectifs de la rééducation","q":"Quel est l'objectif de la rééducation lorsque la déficience n'est pas réductible ?","a":"<p>Lorsque la déficience n'est pas réductible, l'objectif de la rééducation est de <strong>réduire les conséquences</strong>, c'est-à-dire les <strong>limitation d'activité</strong> et les <strong>restrictions de participation</strong>.</p>"},{"i":"9b0513583129","n":122,"o":"122-5","u":"Prise en charge","t":"Connaître les principaux objectifs de la rééducation","q":"Quelle est la nuance entre la rééducation et la réadaptation ?","a":"<p>La <strong>rééducation</strong> vise à aider l'individu à <strong>réduire les déficiences et les limitations d'activités</strong>. La <strong>réadaptation</strong>, quant à elle, vise à l'aider à <strong>s'adapter à des déficiences et des limitations qui sont stabilisées et persistantes</strong>.</p>"},{"i":"0cd6ad2eb01f","n":122,"o":"122-6","u":"Prise en charge","t":"Connaître les principales indications d’un programme de kinésithérapie","q":"Quelles sont les principales indications de kinésithérapie en lien avec la douleur et la trophicité, selon le référentiel de l'EDN ?","a":"<ul><li><strong>Douleur</strong></li><li><strong>Œdème</strong></li><li><strong>Troubles trophiques</strong></li><li><strong>Troubles sensitifs</strong></li></ul>"},{"i":"5087a7e382ba","n":122,"o":"122-6","u":"Prise en charge","t":"Connaître les principales indications d’un programme de kinésithérapie","q":"Quelles sont les principales indications de kinésithérapie en cas d'atteinte articulaire ?","a":"<ul><li><strong>Raideurs articulaires</strong></li><li><strong>Instabilité articulaire</strong></li><li><strong>Gênes à la préhension</strong></li></ul>"},{"i":"8829834cb3d2","n":122,"o":"122-6","u":"Prise en charge","t":"Connaître les principales indications d’un programme de kinésithérapie","q":"Quel est le mécanisme de prise en charge par la CPAM des séances de kinésithérapie ?","a":"<p>La CPAM rembourse <strong>sans accord préalable</strong> un nombre limité de séances pour <strong>14 indications</strong> de rééducation référencées. Au-delà de ce nombre, une <strong>demande d'accord préalable</strong> est nécessaire ; dans les autres situations non référencées, aucune demande préalable n'est requise.</p>"},{"i":"9ba52a0e54f7","n":122,"o":"122-6","u":"Prise en charge","t":"Connaître les principales indications d’un programme de kinésithérapie","q":"Quelles sont les principales indications fonctionnelles justifiant un programme de kinésithérapie ?","a":"<ul><li><strong>Intolérance à l'effort</strong></li><li><strong>Gênes aux déplacements</strong></li><li><strong>Encombrement bronchique</strong></li><li><strong>Troubles vésicosphinctériens</strong></li></ul>"},{"i":"e7517bf76f61","n":122,"o":"122-6","u":"Prise en charge","t":"Connaître les principales indications d’un programme de kinésithérapie","q":"Dans quel contexte général recommande-t-on un programme de kinésithérapie ?","a":"<p>Un programme de kinésithérapie est indiqué devant toute <strong>atteinte fonctionnelle</strong>, spécifiquement dans le champ du <strong>mouvement et de la motricité</strong>.</p>"},{"i":"e96447c08810","n":122,"o":"122-6","u":"Prise en charge","t":"Connaître les principales indications d’un programme de kinésithérapie","q":"Quelles sont les principales indications de kinésithérapie ciblant la motricité ?","a":"<ul><li><strong>Altération de la commande motrice</strong></li><li><strong>Faiblesse musculaire</strong></li><li><strong>Troubles du tonus musculaire</strong></li></ul>"},{"i":"0497a7464fb3","n":122,"o":"122-8","u":"Prise en charge","t":"Connaître les principales indications d’un programme d’ergothérapie","q":"Quelles sont les modalités de remboursement des actes d'ergothérapie en France ?","a":"<p>Actuellement, aucun acte d'ergothérapie exercé en libéral n'est <strong>remboursé</strong> par l'Assurance Maladie. Le recours se fait via un service de Médecine Physique et de Réadaptation (<strong>MPR</strong>). En cas de reconnaissance d'un handicap par la <strong>MDPH</strong>, les actes en libéral peuvent être pris en charge via une Prestation de Compensation du Handicap (<strong>PCH</strong>), sous réserve d'une prescription médicale.</p>"},{"i":"471be4ff8059","n":122,"o":"122-8","u":"Prise en charge","t":"Connaître les principales indications d’un programme d’ergothérapie","q":"Quels sont les différents rôles et interventions de l'ergothérapeute ?","a":"<p>L'ergothérapeute évalue les activités du patient, puis propose des <strong>aides techniques</strong> et des <strong>aménagements de l'environnement</strong> (domicile, outils scolaires, plan de travail). Il peut également concevoir et réaliser des <strong>orthèses</strong> de posture ou de fonction.</p>"},{"i":"731524e05723","n":122,"o":"122-8","u":"Prise en charge","t":"Connaître les principales indications d’un programme d’ergothérapie","q":"Quelle est la définition de l'ergothérapie et son objectif principal ?","a":"<p>L'ergothérapie est une « thérapie par le travail » qui a pour objectif de permettre à l'individu d'atteindre ou de maintenir une autonomie maximale dans son environnement quotidien. Elle intervient lorsqu'une <strong>déficience</strong> limite les activités du patient.</p>"},{"i":"8f98fdffb278","n":122,"o":"122-8","u":"Prise en charge","t":"Connaître les principales indications d’un programme d’ergothérapie","q":"Quelles sont les principales indications nécessitant un programme d'ergothérapie ?","a":"<ul><li><strong>Installation et positionnement</strong> du patient.</li><li>Déficience du membre supérieur (motrice, sensitive ou articulaire).</li><li>Pertes d'autonomie liées à des limitations d'activités physiques (par exemple, <strong>troubles de la préhension</strong>, perte d'autonomie dans les déplacements).</li><li>Pertes d'autonomie liées à des limitations cognitives (par exemple, <strong>troubles des fonctions supérieures</strong> comme la mémoire, la praxie, les fonctions exécutives, ou la communication).</li></ul>"},{"i":"6c0287680ebf","n":122,"o":"122-9","u":"Prise en charge","t":"Connaître les principales indications de l’orthophonie","q":"Pour le Domaine 'Sphère ORL et déglutition', quelles sont les principales indications de l'orthophonie ?","a":"Les principales indications de l'orthophonie dans le domaine 'Sphère ORL et déglutition' sont :\n<ul>\n<li>Les <strong>troubles de la déglutition</strong>.</li>\n<li>Les <strong>troubles de la voix</strong> (dysphonie).</li>\n<li>Les <strong>troubles de l'articulation</strong> (dysarthrie).</li>\n</ul>"},{"i":"9bf45da4a783","n":122,"o":"122-9","u":"Prise en charge","t":"Connaître les principales indications de l’orthophonie","q":"Pour le Domaine 'Langage et communication', quelles sont les principales indications de l'orthophonie ?","a":"Les principales indications de l'orthophonie dans le domaine 'Langage et communication' sont :\n<ul>\n<li>Les <strong>difficultés d'intégration scolaire</strong>.</li>\n<li>Les <strong>troubles du langage écrit et oral</strong>.</li>\n<li>Les <strong>troubles de la communication</strong> dans leurs aspects non langagiers.</li>\n</ul>"},{"i":"e6be6993058b","n":122,"o":"122-9","u":"Prise en charge","t":"Connaître les principales indications de l’orthophonie","q":"Quelle est la principale distinction à faire entre les troubles du langage et la dysarthrie ?","a":"Il est essentiel de distinguer les <strong>troubles du langage</strong> (écrit et oral), qui relèvent d'une fonction cognitive, de la <strong>dysarthrie</strong>, qui est un trouble de l'articulation."}]};